Fix only the JSON Schema errors of the listed records, preserving all substantive requirements, thresholds, conditions, exceptions and citations. Do not remove content merely to pass schema checks. Content ambiguities and source-coverage findings are advisory only. Do not rewrite schema-valid records or add new rules for those findings. Keep additions empty. Return ONE JSON object: {"replacements": [{"index": 0, "rule": {}}], "additions": []}. Each replacement must use an index from candidatesToRevise. A rule is the complete revised Rule JSON record, not a JSON patch. Omitted indexes stay unchanged. There is no delete operation. If a problem cannot be resolved from the supplied source, keep the content and explain the ambiguity.
{"issues": [{"index": 7, "id": "mbo-par-2-abs-6-satz-1", "schemaErrors": ["definition: property 'meaning' is not allowed here: it is mutually exclusive with another property of the record that is also present"]}], "candidatesToRevise": [{"index": 7, "rule": {"schemaVersion": "2.0", "id": "mbo-par-2-abs-6-satz-1", "source": {"documentId": "mbo", "documentTitle": "MUSTERBAUORDNUNG", "documentVersion": "2002-11", "language": "de", "citation": "§ 2 Abs. 6 Satz 1", "elements": [{"elementId": "doc/teil-1/par-2/abs-6", "sentenceId": "doc/teil-1/par-2/abs-6/satz-1", "role": "primary", "pdfPages": [8]}]}, "classification": {"type": "definition", "normativeCategory": "definitional", "summary": "Geschosse sind oberirdische Geschosse, wenn ihre Deckenoberkanten im Mittel mehr als 1,40 m über die Geländeoberfläche hinausragen; im Übrigen sind sie Kellergeschosse."}, "definition": {"term": "oberirdisches Geschoss / Kellergeschoss", "text": "Geschosse sind oberirdische Geschosse, wenn ihre Deckenoberkanten im Mittel mehr als 1,40 m über die Geländeoberfläche hinausragen; im Übrigen sind sie Kellergeschosse.", "meaning": {"kind": "numeric", "fact": "storey.ceiling_top_above_ground_mean", "operator": ">", "value": 1.4, "unit": "m", "description": "Deckenoberkante des Geschosses im Mittel über der Geländeoberfläche; bei mehr als 1,40 m: oberirdisches Geschoss, sonst Kellergeschoss."}}, "review": {"status": "draft", "machineCheckable": true, "checkMethods": ["ids"]}}}], "existingRecords": [{"index": 0, "id": "mbo-par-2-abs-1-satz-1", "source": {"documentId": "mbo", "documentTitle": "MUSTERBAUORDNUNG", "documentVersion": "2002-11", "language": "de", "citation": "§ 2 Abs. 1 Satz 1", "elements": [{"elementId": "doc/teil-1/par-2/abs-1", "sentenceId": "doc/teil-1/par-2/abs-1/satz-1", "role": "primary", "pdfPages": [5]}]}, "classification": {"type": "definition", "normativeCategory": "definitional", "summary": "Bauliche Anlagen sind mit dem Erdboden verbundene, aus Bauprodukten hergestellte Anlagen; eine Verbindung mit dem Boden besteht auch bei Ruhen durch eigene Schwere, begrenzter Beweglichkeit auf ortsfesten Bahnen oder überwiegend ortsfester Nutzungsbestimmung."}}, {"index": 1, "id": "mbo-par-2-abs-1-satz-2", "source": {"documentId": "mbo", "documentTitle": "MUSTERBAUORDNUNG", "documentVersion": "2002-11", "language": "de", "citation": "§ 2 Abs. 1 Satz 2", "elements": [{"elementId": "doc/teil-1/par-2/abs-1", "sentenceId": "doc/teil-1/par-2/abs-1/satz-2", "role": "primary", "pdfPages": [5]}, {"elementId": "doc/teil-1/par-2/abs-1/nr-1", "role": "primary", "pdfPages": [5]}, {"elementId": "doc/teil-1/par-2/abs-1/nr-2", "role": "primary", "pdfPages": [5]}, {"elementId": "doc/teil-1/par-2/abs-1/nr-3", "role": "primary", "pdfPages": [5]}, {"elementId": "doc/teil-1/par-2/abs-1/nr-4", "role": "primary", "pdfPages": [5]}, {"elementId": "doc/teil-1/par-2/abs-1/nr-5", "role": "primary", "pdfPages": [5]}, {"elementId": "doc/teil-1/par-2/abs-1/nr-6", "role": "primary", "pdfPages": [5]}, {"elementId": "doc/teil-1/par-2/abs-1/nr-7", "role": "primary", "pdfPages": [5]}, {"elementId": "doc/teil-1/par-2/abs-1/nr-8", "role": "primary", "pdfPages": [5]}]}, "classification": {"type": "definition", "normativeCategory": "definitional", "summary": "Bauliche Anlagen sind auch Aufschüttungen und Abgrabungen, Lagerplätze, Abstellplätze und Ausstellungsplätze, Sport- und Spielflächen, Campingplätze, Wochenendplätze und Zeltplätze, Freizeit- und Vergnügungsparks, Stellplätze für Kraftfahrzeuge und Abstellplätze für Fahrräder, Gerüste sowie Hilfseinrichtungen zur statischen Sicherung von Bauzuständen."}}, {"index": 2, "id": "mbo-par-2-abs-1-satz-3", "source": {"documentId": "mbo", "documentTitle": "MUSTERBAUORDNUNG", "documentVersion": "2002-11", "language": "de", "citation": "§ 2 Abs. 1 Satz 3", "elements": [{"elementId": "doc/teil-1/par-2/abs-1/txt-1", "sentenceId": "doc/teil-1/par-2/abs-1/satz-3", "role": "primary", "pdfPages": [6]}]}, "classification": {"type": "definition", "normativeCategory": "definitional", "summary": "Anlagen sind bauliche Anlagen und sonstige Anlagen und Einrichtungen im Sinne des § 1 Abs. 1 Satz 2."}}, {"index": 3, "id": "mbo-par-2-abs-2", "source": {"documentId": "mbo", "documentTitle": "MUSTERBAUORDNUNG", "documentVersion": "2002-11", "language": "de", "citation": "§ 2 Abs. 2", "elements": [{"elementId": "doc/teil-1/par-2/abs-2", "sentenceId": "doc/teil-1/par-2/abs-2/s1", "role": "primary", "pdfPages": [6]}]}, "classification": {"type": "definition", "normativeCategory": "definitional", "summary": "Gebäude sind selbstständig benutzbare, überdeckte bauliche Anlagen, die von Menschen betreten werden können und geeignet oder bestimmt sind, dem Schutz von Menschen, Tieren oder Sachen zu dienen."}}, {"index": 4, "id": "mbo-par-2-abs-3-satz-1", "source": {"documentId": "mbo", "documentTitle": "MUSTERBAUORDNUNG", "documentVersion": "2002-11", "language": "de", "citation": "§ 2 Abs. 3 Satz 1", "elements": [{"elementId": "doc/teil-1/par-2/abs-3", "sentenceId": "doc/teil-1/par-2/abs-3/satz-1", "role": "primary", "pdfPages": [6]}, {"elementId": "doc/teil-1/par-2/abs-3/nr-1", "role": "primary", "pdfPages": [6]}, {"elementId": "doc/teil-1/par-2/abs-3/nr-1/lit-a", "role": "primary", "pdfPages": [6]}, {"elementId": "doc/teil-1/par-2/abs-3/nr-1/lit-b", "role": "primary", "pdfPages": [6]}, {"elementId": "doc/teil-1/par-2/abs-3/nr-2", "role": "primary", "pdfPages": [6]}, {"elementId": "doc/teil-1/par-2/abs-3/nr-2/txt-1", "role": "primary", "pdfPages": [6]}, {"elementId": "doc/teil-1/par-2/abs-3/nr-3", "role": "primary", "pdfPages": [6]}, {"elementId": "doc/teil-1/par-2/abs-3/nr-3/txt-1", "role": "primary", "pdfPages": [6]}, {"elementId": "doc/teil-1/par-2/abs-3/nr-4", "role": "primary", "pdfPages": [6]}, {"elementId": "doc/teil-1/par-2/abs-3/nr-4/txt-1", "role": "primary", "pdfPages": [6]}, {"elementId": "doc/teil-1/par-2/abs-3/nr-5", "role": "primary", "pdfPages": [6]}, {"elementId": "doc/teil-1/par-2/abs-3/nr-5/txt-1", "role": "primary", "pdfPages": [6]}, {"elementId": "doc/teil-1/par-2/abs-3/txt-1", "sentenceId": "doc/teil-1/par-2/abs-3/satz-2", "role": "primary", "pdfPages": [6]}, {"elementId": "doc/teil-1/par-2/abs-3/txt-1", "sentenceId": "doc/teil-1/par-2/abs-3/satz-3", "role": "primary", "pdfPages": [6]}]}, "classification": {"type": "definition", "normativeCategory": "definitional", "summary": "Gebäude werden in fünf Gebäudeklassen eingeteilt; die Höhe ist das Maß der Fußbodenoberkante des höchstgelegenen Geschosses mit möglichem Aufenthaltsraum über der mittleren Geländeoberfläche; Brutto-Grundflächen ohne Kellergeschosse sind maßgeblich."}}, {"index": 5, "id": "mbo-par-2-abs-4", "source": {"documentId": "mbo", "documentTitle": "MUSTERBAUORDNUNG", "documentVersion": "2002-11", "language": "de", "citation": "§ 2 Abs. 4", "elements": [{"elementId": "doc/teil-1/par-2/abs-4", "sentenceId": "doc/teil-1/par-2/abs-4/s1", "role": "primary", "pdfPages": [6]}, {"elementId": "doc/teil-1/par-2/abs-4/nr-1", "role": "primary", "pdfPages": [6]}, {"elementId": "doc/teil-1/par-2/abs-4/nr-2", "role": "primary", "pdfPages": [6]}, {"elementId": "doc/teil-1/par-2/abs-4/nr-3", "role": "primary", "pdfPages": [7]}, {"elementId": "doc/teil-1/par-2/abs-4/nr-4", "role": "primary", "pdfPages": [7]}, {"elementId": "doc/teil-1/par-2/abs-4/nr-5", "role": "primary", "pdfPages": [7]}, {"elementId": "doc/teil-1/par-2/abs-4/nr-6", "role": "primary", "pdfPages": [7]}, {"elementId": "doc/teil-1/par-2/abs-4/nr-7", "role": "primary", "pdfPages": [7]}, {"elementId": "doc/teil-1/par-2/abs-4/nr-7/lit-a", "role": "primary", "pdfPages": [7]}, {"elementId": "doc/teil-1/par-2/abs-4/nr-7/lit-b", "role": "primary", "pdfPages": [7]}, {"elementId": "doc/teil-1/par-2/abs-4/nr-8", "role": "primary", "pdfPages": [7]}, {"elementId": "doc/teil-1/par-2/abs-4/nr-9", "role": "primary", "pdfPages": [7]}, {"elementId": "doc/teil-1/par-2/abs-4/nr-9/lit-a", "role": "primary", "pdfPages": [7]}, {"elementId": "doc/teil-1/par-2/abs-4/nr-9/lit-b", "role": "primary", "pdfPages": [7]}, {"elementId": "doc/teil-1/par-2/abs-4/nr-9/lit-c", "role": "primary", "pdfPages": [7]}, {"elementId": "doc/teil-1/par-2/abs-4/nr-10", "role": "primary", "pdfPages": [7]}, {"elementId": "doc/teil-1/par-2/abs-4/nr-11", "role": "primary", "pdfPages": [7]}, {"elementId": "doc/teil-1/par-2/abs-4/nr-12", "role": "primary", "pdfPages": [7]}, {"elementId": "doc/teil-1/par-2/abs-4/nr-13", "role": "primary", "pdfPages": [7]}, {"elementId": "doc/teil-1/par-2/abs-4/nr-14", "role": "primary", "pdfPages": [8]}, {"elementId": "doc/teil-1/par-2/abs-4/nr-15", "role": "primary", "pdfPages": [8]}, {"elementId": "doc/teil-1/par-2/abs-4/nr-16", "role": "primary", "pdfPages": [8]}, {"elementId": "doc/teil-1/par-2/abs-4/nr-17", "role": "primary", "pdfPages": [8]}, {"elementId": "doc/teil-1/par-2/abs-4/nr-18", "role": "primary", "pdfPages": [8]}, {"elementId": "doc/teil-1/par-2/abs-4/nr-19", "role": "primary", "pdfPages": [8]}, {"elementId": "doc/teil-1/par-2/abs-4/nr-20", "role": "primary", "pdfPages": [8]}]}, "classification": {"type": "definition", "normativeCategory": "definitional", "summary": "Sonderbauten sind Anlagen und Räume besonderer Art oder Nutzung, die einen der in Nummern 1 bis 20 aufgeführten Tatbestände erfüllen (u. a. Hochhäuser, große Gebäude, Versammlungsstätten, Krankenhäuser, Schulen)."}}, {"index": 6, "id": "mbo-par-2-abs-5", "source": {"documentId": "mbo", "documentTitle": "MUSTERBAUORDNUNG", "documentVersion": "2002-11", "language": "de", "citation": "§ 2 Abs. 5", "elements": [{"elementId": "doc/teil-1/par-2/abs-5", "sentenceId": "doc/teil-1/par-2/abs-5/s1", "role": "primary", "pdfPages": [8]}]}, "classification": {"type": "definition", "normativeCategory": "definitional", "summary": "Aufenthaltsräume sind Räume, die zum nicht nur vorübergehenden Aufenthalt von Menschen bestimmt oder geeignet sind."}}, {"index": 7, "id": "mbo-par-2-abs-6-satz-1", "source": {"documentId": "mbo", "documentTitle": "MUSTERBAUORDNUNG", "documentVersion": "2002-11", "language": "de", "citation": "§ 2 Abs. 6 Satz 1", "elements": [{"elementId": "doc/teil-1/par-2/abs-6", "sentenceId": "doc/teil-1/par-2/abs-6/satz-1", "role": "primary", "pdfPages": [8]}]}, "classification": {"type": "definition", "normativeCategory": "definitional", "summary": "Geschosse sind oberirdische Geschosse, wenn ihre Deckenoberkanten im Mittel mehr als 1,40 m über die Geländeoberfläche hinausragen; im Übrigen sind sie Kellergeschosse."}}, {"index": 8, "id": "mbo-par-2-abs-6-satz-2", "source": {"documentId": "mbo", "documentTitle": "MUSTERBAUORDNUNG", "documentVersion": "2002-11", "language": "de", "citation": "§ 2 Abs. 6 Satz 2", "elements": [{"elementId": "doc/teil-1/par-2/abs-6", "sentenceId": "doc/teil-1/par-2/abs-6/satz-2", "role": "primary", "pdfPages": [8]}]}, "classification": {"type": "definition", "normativeCategory": "definitional", "summary": "Hohlräume zwischen der obersten Decke und der Bedachung, in denen Aufenthaltsräume nicht möglich sind, sind keine Geschosse."}}, {"index": 9, "id": "mbo-par-2-abs-7-satz-1", "source": {"documentId": "mbo", "documentTitle": "MUSTERBAUORDNUNG", "documentVersion": "2002-11", "language": "de", "citation": "§ 2 Abs. 7 Satz 1", "elements": [{"elementId": "doc/teil-1/par-2/abs-7", "sentenceId": "doc/teil-1/par-2/abs-7/satz-1", "role": "primary", "pdfPages": [8]}]}, "classification": {"type": "definition", "normativeCategory": "definitional", "summary": "Stellplätze sind Flächen, die dem Abstellen von Kraftfahrzeugen außerhalb der öffentlichen Verkehrsflächen dienen."}}, {"index": 10, "id": "mbo-par-2-abs-7-satz-2", "source": {"documentId": "mbo", "documentTitle": "MUSTERBAUORDNUNG", "documentVersion": "2002-11", "language": "de", "citation": "§ 2 Abs. 7 Satz 2", "elements": [{"elementId": "doc/teil-1/par-2/abs-7", "sentenceId": "doc/teil-1/par-2/abs-7/satz-2", "role": "primary", "pdfPages": [8]}]}, "classification": {"type": "definition", "normativeCategory": "definitional", "summary": "Garagen sind Gebäude oder Gebäudeteile zum Abstellen von Kraftfahrzeugen."}}, {"index": 11, "id": "mbo-par-2-abs-7-satz-3", "source": {"documentId": "mbo", "documentTitle": "MUSTERBAUORDNUNG", "documentVersion": "2002-11", "language": "de", "citation": "§ 2 Abs. 7 Satz 3", "elements": [{"elementId": "doc/teil-1/par-2/abs-7", "sentenceId": "doc/teil-1/par-2/abs-7/satz-3", "role": "primary", "pdfPages": [8]}]}, "classification": {"type": "definition", "normativeCategory": "definitional", "summary": "Ausstellungs-, Verkaufs-, Werk- und Lagerräume für Kraftfahrzeuge sind keine Stellplätze oder Garagen."}}, {"index": 12, "id": "mbo-par-2-abs-8", "source": {"documentId": "mbo", "documentTitle": "MUSTERBAUORDNUNG", "documentVersion": "2002-11", "language": "de", "citation": "§ 2 Abs. 8", "elements": [{"elementId": "doc/teil-1/par-2/abs-8", "sentenceId": "doc/teil-1/par-2/abs-8/s1", "role": "primary", "pdfPages": [8]}]}, "classification": {"type": "definition", "normativeCategory": "definitional", "summary": "Feuerstätten sind in oder an Gebäuden ortsfest benutzte Anlagen oder Einrichtungen, die dazu bestimmt sind, durch Verbrennung Wärme zu erzeugen."}}, {"index": 13, "id": "mbo-par-2-abs-9", "source": {"documentId": "mbo", "documentTitle": "MUSTERBAUORDNUNG", "documentVersion": "2002-11", "language": "de", "citation": "§ 2 Abs. 9", "elements": [{"elementId": "doc/teil-1/par-2/abs-9", "sentenceId": "doc/teil-1/par-2/abs-9/s1", "role": "primary", "pdfPages": [8]}]}, "classification": {"type": "definition", "normativeCategory": "definitional", "summary": "Barrierefrei sind bauliche Anlagen, soweit sie für Menschen mit Behinderung in der allgemein üblichen Weise, ohne besondere Erschwernis und grundsätzlich ohne fremde Hilfe auffindbar, zugänglich und nutzbar sind."}}, {"index": 14, "id": "mbo-par-2-abs-10", "source": {"documentId": "mbo", "documentTitle": "MUSTERBAUORDNUNG", "documentVersion": "2002-11", "language": "de", "citation": "§ 2 Abs. 10", "elements": [{"elementId": "doc/teil-1/par-2/abs-10", "sentenceId": "doc/teil-1/par-2/abs-10/s1", "role": "primary", "pdfPages": [8]}, {"elementId": "doc/teil-1/par-2/abs-10/nr-1", "role": "primary", "pdfPages": [8]}, {"elementId": "doc/teil-1/par-2/abs-10/nr-2", "role": "primary", "pdfPages": [8]}, {"elementId": "doc/teil-1/par-2/abs-10/txt-1", "role": "primary", "pdfPages": [8]}]}, "classification": {"type": "definition", "normativeCategory": "definitional", "summary": "Bauprodukte sind Produkte, Baustoffe, Bauteile und Anlagen sowie Bausätze gemäß Art. 2 Nr. 2 der Verordnung (EU) Nr. 305/2011, die dauerhaft in bauliche Anlagen eingebaut werden sollen, sowie vorgefertigte Anlagen, die mit dem Erdboden verbunden werden sollen, sofern ihre Verwendung sich auf die Anforderungen nach § 3 Satz 1 auswirken kann."}}, {"index": 15, "id": "mbo-par-2-abs-11", "source": {"documentId": "mbo", "documentTitle": "MUSTERBAUORDNUNG", "documentVersion": "2002-11", "language": "de", "citation": "§ 2 Abs. 11", "elements": [{"elementId": "doc/teil-1/par-2/abs-11", "sentenceId": "doc/teil-1/par-2/abs-11/s1", "role": "primary", "pdfPages": [8]}]}, "classification": {"type": "definition", "normativeCategory": "definitional", "summary": "Bauart ist das Zusammenfügen von Bauprodukten zu baulichen Anlagen oder Teilen von baulichen Anlagen."}}]}
