{"rules":[{"schemaVersion":"2.0","id":"mbo-par-6-abs-1-satz-1","source":{"documentId":"mbo","documentTitle":"MUSTERBAUORDNUNG","language":"de","citation":"§ 6 Abs. 1 Satz 1","elements":[{"elementId":"doc/teil-2/par-6/abs-1","sentenceId":"doc/teil-2/par-6/abs-1/satz-1","role":"primary"}]},"classification":{"type":"obligation","normativeCategory":"substantive","summary":"Vor den Außenwänden von Gebäuden sind Abstandsflächen von oberirdischen Gebäuden freizuhalten."},"applicability":{"targets":[{"entity":"Abstandsfläche","entityType":"setback_area","description":"Fläche vor den Außenwänden von Gebäuden"}]},"requirements":[{"kind":"boolean","fact":"setback_area_kept_free_from_above_ground_buildings","value":true,"description":"Die Abstandsfläche vor den Außenwänden von Gebäuden ist von oberirdischen Gebäuden freizuhalten."}],"review":{"status":"draft","machineCheckable":true,"checkMethods":["ids"]}}
,{"schemaVersion":"2.0","id":"mbo-par-6-abs-1-satz-2","source":{"documentId":"mbo","documentTitle":"MUSTERBAUORDNUNG","language":"de","citation":"§ 6 Abs. 1 Satz 2","elements":[{"elementId":"doc/teil-2/par-6/abs-1","sentenceId":"doc/teil-2/par-6/abs-1/satz-2","role":"primary"}]},"classification":{"type":"obligation","normativeCategory":"substantive","summary":"Satz 1 gilt entsprechend für andere Anlagen, von denen Wirkungen wie von Gebäuden ausgehen, gegenüber Gebäuden und Grundstücksgrenzen."},"applicability":{"targets":[{"entity":"andere Anlage","entityType":"structure_with_building_like_effects","description":"Anlagen, von denen Wirkungen wie von Gebäuden ausgehen"}]},"requirements":[{"kind":"boolean","fact":"setback_area_kept_free_from_above_ground_buildings","value":true,"description":"Abstandsflächen sind auch gegenüber Gebäuden und Grundstücksgrenzen freizuhalten."}],"references":[{"citation":"§ 6 Abs. 1 Satz 1","elementId":"doc/teil-2/par-6/abs-1","resolution":"resolved","relationship":"depends_on"}],"review":{"status":"draft","machineCheckable":false,"checkMethods":["manual"],"ambiguities":["Der Begriff 'Wirkungen wie von Gebäuden' ist auslegungsbedürftig."]}}
,{"schemaVersion":"2.0","id":"mbo-par-6-abs-1-satz-3","source":{"documentId":"mbo","documentTitle":"MUSTERBAUORDNUNG","language":"de","citation":"§ 6 Abs. 1 Satz 3","elements":[{"elementId":"doc/teil-2/par-6/abs-1","sentenceId":"doc/teil-2/par-6/abs-1/satz-3","role":"primary"}]},"classification":{"type":"exception","normativeCategory":"substantive","summary":"Satz 2 gilt nicht für Antennen im Außenbereich einschließlich der Masten mit einer maximalen Breite von 1,50 m und einer Gesamthöhe von nicht mehr als 50 m gegenüber anderen Grundstücken im Außenbereich."},"applicability":{"targets":[{"entity":"Antenne im Außenbereich","entityType":"antenna_with_mast","description":"Antennen im Außenbereich einschließlich der Masten"}],"conditions":{"kind":"all","conditions":[{"kind":"comparison","fact":"mast_width","operator":"<=","value":1.5,"valueType":"number","unit":"m"},{"kind":"comparison","fact":"structure_total_height","operator":"<=","value":50,"valueType":"number","unit":"m"},{"kind":"comparison","fact":"neighbouring_plot_location","operator":"==","value":"Außenbereich","valueType":"string"}]}},"requirements":[{"kind":"boolean","fact":"setback_area_required_towards_other_plots_in_outside_area","value":false,"description":"Gegenüber anderen Grundstücken im Außenbereich ist keine Abstandsfläche erforderlich."}],"references":[{"citation":"§ 6 Abs. 1 Satz 2","elementId":"doc/teil-2/par-6/abs-1","resolution":"resolved","relationship":"related_to"}],"review":{"status":"draft","machineCheckable":true,"checkMethods":["ids"]}}
,{"schemaVersion":"2.0","id":"mbo-par-6-abs-1-satz-4-nr-1","source":{"documentId":"mbo","documentTitle":"MUSTERBAUORDNUNG","language":"de","citation":"§ 6 Abs. 1 Satz 4 Nr. 1","elements":[{"elementId":"doc/teil-2/par-6/abs-1","sentenceId":"doc/teil-2/par-6/abs-1/satz-4","role":"primary"},{"elementId":"doc/teil-2/par-6/abs-1/nr-1","sentenceId":"doc/teil-2/par-6/abs-1/satz-4","role":"primary"}]},"classification":{"type":"exception","normativeCategory":"substantive","summary":"Eine Abstandsfläche ist nicht erforderlich vor Außenwänden, die an Grundstücksgrenzen errichtet werden, wenn nach planungsrechtlichen Vorschriften an die Grenze gebaut werden muss oder darf."},"applicability":{"targets":[{"entity":"Außenwand","entityType":"exterior_wall","description":"Außenwände, die an Grundstücksgrenzen errichtet werden"}],"conditions":{"kind":"comparison","fact":"building_at_boundary_permitted_or_required_by_planning_law","operator":"==","value":true,"valueType":"boolean"}},"requirements":[{"kind":"boolean","fact":"setback_area_required","value":false,"description":"Eine Abstandsfläche ist nicht erforderlich."}],"review":{"status":"draft","machineCheckable":false,"checkMethods":["manual"],"ambiguities":["Die Frage, ob planungsrechtliche Vorschriften das Bauen an der Grenze vorschreiben oder erlauben, erfordert externe Prüfung."]}}
