,{"schemaVersion":"2.0","id":"mbo-par-6-abs-3","source":{"documentId":"mbo","documentTitle":"MUSTERBAUORDNUNG","language":"de","citation":"§ 6 Abs. 3","elements":[{"elementId":"doc/teil-2/par-6/abs-3","sentenceId":"doc/teil-2/par-6/abs-3/s1","role":"primary"},{"elementId":"doc/teil-2/par-6/abs-3/nr-1","sentenceId":"doc/teil-2/par-6/abs-3/s1","role":"primary"},{"elementId":"doc/teil-2/par-6/abs-3/nr-2","sentenceId":"doc/teil-2/par-6/abs-3/s1","role":"primary"},{"elementId":"doc/teil-2/par-6/abs-3/nr-3","sentenceId":"doc/teil-2/par-6/abs-3/s1","role":"primary"}]},"classification":{"type":"prohibition","normativeCategory":"substantive","summary":"Abstandsflächen dürfen sich nicht überdecken; dies gilt nicht für Außenwände in einem Winkel von mehr als 75 Grad zueinander, für Außenwände zu einem fremder Sicht entzogenen Gartenhof bei Wohngebäuden der Gebäudeklassen 1 und 2, sowie für Gebäude und andere bauliche Anlagen, die in den Abstandsflächen zulässig sind."},"applicability":{"targets":[{"entity":"Abstandsfläche","entityType":"setback_area"}]},"requirements":[{"kind":"boolean","fact":"setback_areas_overlap","value":false,"description":"Abstandsflächen dürfen sich nicht überdecken."}],"exceptions":[{"kind":"exception","effect":"disapplies_rule","description":"Das Überdeckungsverbot gilt nicht für Außenwände, die in einem Winkel von mehr als 75 Grad zueinander stehen.","condition":{"kind":"comparison","fact":"angle_between_exterior_walls","operator":">","value":75,"valueType":"number","unit":"deg"}},{"kind":"exception","effect":"disapplies_rule","description":"Das Überdeckungsverbot gilt nicht für Außenwände zu einem fremder Sicht entzogenen Gartenhof bei Wohngebäuden der Gebäudeklassen 1 und 2.","condition":{"kind":"all","conditions":[{"kind":"comparison","fact":"wall_faces_private_garden_courtyard","operator":"==","value":true,"valueType":"boolean"},{"kind":"comparison","fact":"building_class","operator":"in","value":[1,2],"valueType":"integer_array"}]}},{"kind":"exc