,{"schemaVersion":"2.0","id":"mbo-par-6-abs-6-nr-1","source":{"documentId":"mbo","documentTitle":"MUSTERBAUORDNUNG","language":"de","citation":"§ 6 Abs. 6 Nr. 1","elements":[{"elementId":"doc/teil-2/par-6/abs-6","sentenceId":"doc/teil-2/par-6/abs-6/s1","role":"primary"},{"elementId":"doc/teil-2/par-6/abs-6/nr-1","sentenceId":"doc/teil-2/par-6/abs-6/s1","role":"primary"}]},"classification":{"type":"permission","normativeCategory":"substantive","summary":"Bei der Bemessung der Abstandsflächen bleiben vor die Außenwand vortretende Bauteile wie Gesimse und Dachüberstände außer Betracht."},"applicability":{"targets":[{"entity":"vortretendes Bauteil","entityType":"projecting_building_component","description":"Vor die Außenwand vortretende Bauteile wie Gesimse und Dachüberstände"}],"actors":[{"role":"beneficiary","entity":"Bauherr"}]},"requirements":[{"kind":"boolean","fact":"projecting_component_disregarded_in_setback_calculation","value":true,"description":"Vor die Außenwand vortretende Bauteile wie Gesimse und Dachüberstände bleiben bei der Bemessung der Abstandsflächen außer Betracht."}],"review":{"status":"draft","machineCheckable":true,"checkMethods":["ids"]}}
