,{"schemaVersion":"2.0","id":"mbo-par-6-abs-8-satz-1-nr-1","source":{"documentId":"mbo","documentTitle":"MUSTERBAUORDNUNG","language":"de","citation":"§ 6 Abs. 8 Satz 1 Nr. 1","elements":[{"elementId":"doc/teil-2/par-6/abs-8","sentenceId":"doc/teil-2/par-6/abs-8/satz-1","role":"primary"},{"elementId":"doc/teil-2/par-6/abs-8/nr-1","sentenceId":"doc/teil-2/par-6/abs-8/satz-1","role":"primary"},{"elementId":"doc/teil-2/par-6/abs-8/txt-1","sentenceId":"doc/teil-2/par-6/abs-8/satz-2","role":"primary"}]},"classification":{"type":"permission","normativeCategory":"substantive","summary":"In den Abstandsflächen eines Gebäudes sowie ohne eigene Abstandsflächen sind Garagen und Gebäude ohne Aufenthaltsräume und Feuerstätten mit einer mittleren Wandhöhe bis zu 3 m und einer Gesamtlänge je Grundstücksgrenze von 9 m zulässig, auch wenn sie nicht an die Grundstücksgrenze oder an das Gebäude angebaut werden. Die Gesamtlänge der die Abstandsflächentiefe nicht einhaltenden Bebauung nach Nr. 1 und 2 darf auf einem Grundstück insgesamt 15 m nicht überschreiten."},"applicability":{"targets":[{"entity":"Garage oder Gebäude ohne Aufenthaltsräume und Feuerstätten","entityType":"garage_or_ancillary_building","description":"Garagen und Gebäude ohne Aufenthaltsräume und Feuerstätten"}],"actors":[{"role":"beneficiary","entity":"Bauherr"}],"conditions":{"kind":"all","conditions":[{"kind":"comparison","fact":"building_mean_wall_height","operator":"<=","value":3,"valueType":"number","unit":"m"},{"kind":"comparison","fact":"building_total_length_per_plot_boundary","operator":"<=","value":9,"valueType":"number","unit":"m"}]}},"requirements":[{"kind":"boolean","fact":"structure_permitted_within_setback_area_without_own_setback","value":true,"description":"Garagen und Gebäude ohne Aufenthaltsräume und Feuerstätten sind in den Abstandsflächen sowie ohne eigene Abstandsflächen zulässig, auch wenn sie nicht an die Grundstücksgrenze oder an das Gebäude angebaut werden."}],"exceptions":[{"kind":"exception","effect":"modifies_rule","description":"Die Gesamtlänge der die Abstandsflächentiefe gegenüber den Grundstücksgrenzen nicht einhaltenden Bebauung nach Nummern 1 und 2 darf auf einem Grundstück insgesamt 15 m nicht überschreiten.","requirements":[{"kind":"numeric","fact":"total_length_of_non_compliant_structures_per_plot","operator":"<=","value":15,"unit":"m","description":"Gesamtlänge der die Abstandsflächentiefe nicht einhaltenden Bebauung nach Nr. 1 und 2 je Grundstück."}]}],"review":{"status":"draft","machineCheckable":true,"checkMethods":["ids"]}}
