        "type": "permission",
        "normativeCategory": "substantive",
        "summary": "Der zweite Rettungsweg kann eine weitere notwendige Treppe oder eine mit Rettungsgeräten der Feuerwehr erreichbare Stelle der Nutzungseinheit sein; er ist nicht erforderlich, wenn die Rettung über einen Sicherheitstreppenraum möglich ist."
      },
      "applicability": {
        "targets": [
          {
            "entity": "zweiter Rettungsweg",
