        "kind": "any",
        "requirements": [
          {
            "kind": "requirement",
            "requirement": {
              "kind": "text",
              "fact": "second_escape_route_type",
              "operator": "==",
              "value": "weitere notwendige Treppe",
              "description": "Der zweite Rettungsweg ist eine weitere notwendige Treppe"
