        "status": "draft",
        "machineCheckable": false,
        "checkMethods": ["manual"],
        "ambiguities": [
          "Die Erreichbarkeit mit Rettungsgeräten der Feuerwehr hängt von der tatsächlichen Ausstattung der Feuerwehr ab.",
          "Die Eigenschaft 'Sicherheitstreppenraum' (Feuer und Rauch können nicht eindringen) erfordert qualitative Beurteilung."
        ]
      }
