      "classification": {
        "type": "conditional_requirement",
        "normativeCategory": "substantive",
        "summary": "Gebäude, deren zweiter Rettungsweg über Rettungsgeräte der Feuerwehr führt und bei denen die Brüstungsoberkante der zum Anleitern bestimmten Fenster oder Stellen mehr als 8 m über der Geländeoberfläche liegt, dürfen nur errichtet werden, wenn die Feuerwehr über die erforderlichen Rettungsgeräte (z. B. Hubrettungsfahrzeuge) verfügt."
      },
      "applicability": {
        "targets": [
          {
            "entity": "Gebäude",
            "entityType": "building",
            "description": "Gebäude, deren zweiter Rettungsweg über Rettungsgeräte der Feuerwehr führt"
          }
        ],
        "conditions": {
          "kind": "all",
          "conditions": [
            {
              "kind": "comparison",
              "fact": "second_escape_route_via_fire_brigade_equipment",
              "operator": "==",
              "value": true,
              "valueType": "boolean"
            },
            {
              "kind": "comparison",
              "fact": "parapet_top_height_above_ground",
              "operator": ">",
              "value": 8,
              "valueType": "number"
            }
          ]
        }
      },
      "requirements": [
        {
          "kind": "boolean",
          "fact": "fire_brigade_has_required_rescue_equipment",
          "value": true,
          "description": "Die Feuerwehr muss über die erforderlichen Rettungsgeräte wie Hubrettungsfahrzeuge verfügen"
        }
      ],
      "review": {
        "status": "draft",
        "machineCheckable": false,
        "checkMethods": ["manual"],
        "ambiguities": [
          "Die Verfügbarkeit der Rettungsgeräte bei der Feuerwehr ist eine tatsächliche Voraussetzung, die nicht aus Baudaten allein geprüft werden kann.",
          "Die Einheit der Höhe (parapet_top_height_above_ground) ist m; dies ist aus dem Kontext erschlossen."
        ],
        "notes": [
          "Die Höhe von 8 m bezieht sich auf die Oberkante der Brüstung von zum Anleitern bestimmten Fenstern oder Stellen über der Geländeoberfläche."
        ]
      },
      "externalMappings": [
        {
          "standard": "IFC4",
          "entityClass": "IfcBuilding",
          "notes": "Höhe der Brüstungsoberkante über Gelände ist relevant für die Anwendbarkeit"
        }
      ]
    },
