        "conditions": {
          "kind": "comparison",
          "fact": "second_escape_route_via_fire_brigade_equipment",
          "operator": "==",
          "value": true,
          "valueType": "boolean"
        }
      },
      "requirements": [
        {
          "kind": "boolean",
          "fact": "no_concerns_regarding_person_rescue",
          "value": true,
          "description": "Es dürfen keine Bedenken wegen der Personenrettung bestehen"
        }
      ],
      "review": {
        "status": "draft",
        "machineCheckable": false,
        "checkMethods": ["manual"],
        "ambiguities": [
          "Das Kriterium 'keine Bedenken wegen der Personenrettung' ist unbestimmt und erfordert eine behördliche Beurteilung im Einzelfall."
        ]
      }
    }
