{"rules":[{"schemaVersion":"2.0","id":"mbo-par-39-abs-1-satz-1","source":{"documentId":"mbo","documentTitle":"MUSTERBAUORDNUNG","language":"de","citation":"§ 39 Abs. 1 Satz 1","elements":[{"elementId":"doc/teil-3/abschnitt-6/par-39/abs-1","sentenceId":"doc/teil-3/abschnitt-6/par-39/abs-1/satz-1","role":"primary"}]},"classification":{"type":"obligation","normativeCategory":"substantive","summary":"Aufzüge im Innern von Gebäuden müssen eigene Fahrschächte haben, um eine Brandausbreitung in andere Geschosse ausreichend lang zu verhindern."},"applicability":{"targets":[{"entity":"Aufzug","entityType":"elevator","description":"Aufzüge im Innern von Gebäuden"}]},"requirements":[{"kind":"boolean","fact":"elevator.has_own_shaft","value":true,"description":"Der Aufzug muss einen eigenen Fahrschacht haben, um Brandausbreitung in andere Geschosse ausreichend lang zu verhindern."}],"review":{"status":"draft","machineCheckable":true,"checkMethods":["ids"]}}
,{"schemaVersion":"2.0","id":"mbo-par-39-abs-1-satz-2","source":{"documentId":"mbo","documentTitle":"MUSTERBAUORDNUNG","language":"de","citation":"§ 39 Abs. 1 Satz 2","elements":[{"elementId":"doc/teil-3/abschnitt-6/par-39/abs-1","sentenceId":"doc/teil-3/abschnitt-6/par-39/abs-1/satz-2","role":"primary"}]},"classification":{"type":"obligation","normativeCategory":"substantive","summary":"In einem Fahrschacht dürfen bis zu drei Aufzüge liegen."},"applicability":{"targets":[{"entity":"Fahrschacht","entityType":"elevator_shaft","description":"Fahrschacht im Innern von Gebäuden"}]},"requirements":[{"kind":"numeric","fact":"shaft.elevator_count","operator":"<=","value":3,"unit":"1","description":"In einem Fahrschacht dürfen höchstens drei Aufzüge liegen."}],"review":{"status":"draft","machineCheckable":true,"checkMethods":["ids"]}}
,{"schemaVersion":"2.0","id":"mbo-par-39-abs-1-satz-3","source":{"documentId":"mbo","documentTitle":"MUSTERBAUORDNUNG","language":"de","citation":"§ 39 Abs. 1 Satz 3 Nr. 1–4","elements":[{"elementId":"doc/teil-3/abschnitt-6/par-39/abs-1","sentenceId":"doc/teil-3/abschnitt-6/par-39/abs-1/satz-3","role":"primary"},{"elementId":"doc/teil-3/abschnitt-6/par-39/abs-1/nr-1","role":"primary"},{"elementId":"doc/teil-3/abschnitt-6/par-39/abs-1/nr-2","role":"primary"},{"elementId":"doc/teil-3/abschnitt-6/par-39/abs-1/nr-3","role":"primary"},{"elementId":"doc/teil-3/abschnitt-6/par-39/abs-1/nr-4","role":"primary"}]},"classification":{"type":"permission","normativeCategory":"substantive","summary":"Aufzüge ohne eigene Fahrschächte sind in bestimmten Fällen zulässig: innerhalb eines notwendigen Treppenraumes (nicht in Hochhäusern), innerhalb von Räumen die Geschosse überbrücken, zur Verbindung offen verbundener Geschosse, sowie in Gebäuden der Gebäudeklassen 1 und 2 (mit sicherer Umkleidung)."},"applicability":{"targets":[{"entity":"Aufzug ohne eigenen Fahrschacht","entityType":"elevator_without_own_shaft","description":"Aufzüge ohne eigene Fahrschächte"}]},"requirementExpression":{"kind":"any","requirements":[{"kind":"requirement","requirement":{"kind":"text","fact":"elevator.installation_location","operator":"==","value":"notwendiger_treppenraum","description":"Innerhalb eines notwendigen Treppenraumes (ausgenommen in Hochhäusern)"}},{"kind":"requirement","requirement":{"kind":"text","fact":"elevator.installation_location","operator":"==","value":"raumueberbrueckend","description":"Innerhalb von Räumen, die Geschosse überbrücken"}},{"kind":"requirement","requirement":{"kind":"text","fact":"elevator.installation_location","operator":"==","value":"offen_verbundene_geschosse","description":"Zur Verbindung von Geschossen, die offen miteinander in Verbindung stehen dürfen"}},{"kind":"requirement","requirement":{"kind":"comparison","fact":"building.building_class","operator":"in","value":[1,2],"valueType":"integer_array","description":"In Gebäuden der Gebäudeklassen 1 und 2"}}]},"exceptions":[{"kind":"exception","effect":"disapplies_rule","description":"In Hochhäusern ist die Zulässigkeit nach Nr. 1 (innerhalb eines notwendigen Treppenraumes) nicht gegeben.","condition":{"kind":"comparison","fact":"building.is_high_rise","operator":"==","value":true,"valueType":"boolean"}},{"kind":"alternative","effect":"adds_alternative","description":"Aufzüge ohne eigene Fahrschächte in Gebäuden der Gebäudeklassen 1 und 2 müssen sicher umkleidet sein.","condition":{"kind":"comparison","fact":"building.building_class","operator":"in","value":[1,2],"valueType":"integer_array"},"requirements":[{"kind":"boolean","fact":"elevator.has_secure_enclosure","value":true,"description":"Der Aufzug muss sicher umkleidet sein."}]}],"review":{"status":"draft","machineCheckable":false,"checkMethods":["ids","llm_comparison"],"ambiguities":["Die Zulässigkeitsbedingungen Nr. 1–4 sind alternativ; die genaue Abgrenzung der Installationsorte erfordert Interpretation."]}}
,{"schemaVersion":"2.0","id":"mbo-par-39-abs-2-satz-1","source":{"documentId":"mbo","documentTitle":"MUSTERBAUORDNUNG","language":"de","citation":"§ 39 Abs. 2 Satz 1 Nr. 1–3","elements":[{"elementId":"doc/teil-3/abschnitt-6/par-39/abs-2","sentenceId":"doc/teil-3/abschnitt-6/par-39/abs-2/satz-1","role":"primary"},{"elementId":"doc/teil-3/abschnitt-6/par-39/abs-2/nr-1","role":"primary"},{"elementId":"doc/teil-3/abschnitt-6/par-39/abs-2/nr-2","role":"primary"},{"elementId":"doc/teil-3/abschnitt-6/par-39/abs-2/nr-3","role":"primary"}]},"classification":{"type":"obligation","normativeCategory":"substantive","summary":"Fahrschachtwände müssen als raumabschließende Bauteile je nach Gebäudeklasse feuerbeständig und aus nichtbrennbaren Baustoffen (GK 5), hochfeuerhemmend (GK 4) oder feuerhemmend (GK 3) sein; bei GK 3 müssen Fahrschachtwände aus brennbaren Baustoffen schachtseitig eine Bekleidung aus nichtbrennbaren Baustoffen in ausreichender Dicke haben."},"applicability":{"targets":[{"entity":"Fahrschachtwand","entityType":"elevator_shaft_wall","description":"Fahrschachtwände als raumabschließende Bauteile"}]},"requirementExpression":{"kind":"any","requirements":[{"kind":"requirement","requirement":{"kind":"all","requirements":[{"kind":"requirement","requirement":{"kind":"comparison","fact":"building.building_class","operator":"==","value":5,"valueType":"integer"}},{"kind":"requirement","requirement":{"kind":"text","fact":"shaft_wall.fire_resistance_class","operator":"==","value":"feuerbestaendig","description":"Feuerbeständig"}},{"kind":"requirement","requirement":{"kind":"boolean","fact":"shaft_wall.made_of_non_combustible_materials","value":true,"description":"Aus nichtbrennbaren Baustoffen"}}]}},{"kind":"requirement","requirement":{"kind":"all","requirements":[{"kind":"requirement","requirement":{"kind":"comparison","fact":"building.building_class","operator":"==","value":4,"valueType":"integer"}},{"kind":"requirement","requirement":{"kind":"text","fact":"shaft_wall.fire_resistance_class","operator":"==","value":"hochfeuerhemmend","description":"Hochfeuerhemmend"}}]}},{"kind":"requirement","requirement":{"kind":"all","requirements":[{"kind":"requirement","requirement":{"kind":"comparison","fact":"building.building_class","operator":"==","value":3,"valueType":"integer"}},{"kind":"requirement","requirement":{"kind":"text","fact":"shaft_wall.fire_resistance_class","operator":"==","value":"feuerhemmend","description":"Feuerhemmend"}}]}}]},"exceptions":[{"kind":"alternative","effect":"adds_alternative","description":"Fahrschachtwände aus brennbaren Baustoffen in Gebäuden der Gebäudeklasse 3 müssen schachtseitig eine Bekleidung aus nichtbrennbaren Baustoffen in ausreichender Dicke haben.","condition":{"kind":"all","conditions":[{"kind":"comparison","fact":"building.building_class","operator":"==","value":3,"valueType":"integer"},{"kind":"comparison","fact":"shaft_wall.made_of_combustible_materials","operator":"==","value":true,"valueType":"boolean"}]},"requirements":[{"kind":"boolean","fact":"shaft_wall.has_non_combustible_lining_on_shaft_side","value":true,"description":"Schachtseitige Bekleidung aus nichtbrennbaren Baustoffen in ausreichender Dicke"}]}],"review":{"status":"draft","machineCheckable":false,"checkMethods":["ids","llm_comparison"],"ambiguities":["Die Anforderung gilt je nach Gebäudeklasse; die Gebäudeklassen 1 und 2 sind nicht explizit geregelt."]}}
,{"schemaVersion":"2.0","id":"mbo-par-39-abs-2-satz-2","source":{"documentId":"mbo","documentTitle":"MUSTERBAUORDNUNG","language":"de","citation":"§ 39 Abs. 2 Satz 2","elements":[{"elementId":"doc/teil-3/abschnitt-6/par-39/abs-2/nr-3","sentenceId":"doc/teil-3/abschnitt-6/par-39/abs-2/satz-2","role":"primary"}]},"classification":{"type":"obligation","normativeCategory":"substantive","summary":"Fahrschachttüren und andere Öffnungen in Fahrschachtwänden mit erforderlicher Feuerwiderstandsfähigkeit sind so herzustellen, dass die Anforderungen nach § 39 Abs. 1 Satz 1 nicht beeinträchtigt werden."},"applicability":{"targets":[{"entity":"Fahrschachttür","entityType":"elevator_shaft_door","description":"Fahrschachttüren und andere Öffnungen in Fahrschachtwänden mit erforderlicher Feuerwiderstandsfähigkeit"},{"entity":"Öffnung in Fahrschachtwand","entityType":"elevator_shaft_opening"}]},"requirements":[{"kind":"boolean","fact":"shaft_door_or_opening.does_not_impair_fire_spread_prevention","value":true,"description":"Fahrschachttüren und Öffnungen müssen so hergestellt sein, dass die Anforderungen nach § 39 Abs. 1 Satz 1 (Verhinderung der Brandausbreitung) nicht beeinträchtigt werden."}],"references":[{"citation":"§ 39 Abs. 1 Satz 1","elementId":"doc/teil-3/abschnitt-6/par-39/abs-1","resolution":"resolved","relationship":"depends_on"}],"review":{"status":"draft","machineCheckable":false,"checkMethods":["llm_comparison"],"ambiguities":["Die Anforderung ist funktional formuliert; eine maschinelle Prüfung erfordert Interpretation."]}}
,{"schemaVersion":"2.0","id":"mbo-par-39-abs-3-satz-1","source":{"documentId":"mbo","documentTitle":"MUSTERBAUORDNUNG","language":"de","citation":"§ 39 Abs. 3 Satz 1","elements":[{"elementId":"doc/teil-3/abschnitt-6/par-39/abs-3","sentenceId":"doc/teil-3/abschnitt-6/par-39/abs-3/satz-1","role":"primary"}]},"classification":{"type":"obligation","normativeCategory":"substantive","summary":"Fahrschächte müssen zu lüften sein und eine Öffnung zur Rauchableitung haben mit einem freien Querschnitt von mindestens 2,5 v. H. der Fahrschachtgrundfläche, mindestens jedoch 0,10 m²."},"applicability":{"targets":[{"entity":"Fahrschacht","entityType":"elevator_shaft"}]},"requirements":[{"kind":"boolean","fact":"shaft.is_ventilatable","value":true,"description":"Fahrschächte müssen zu lüften sein."},{"kind":"formula","fact":"smoke_exhaust_opening.free_cross_section","operator":"==","unit":"m2","expression":{"kind":"operation","operator":"max","operands":[{"kind":"operation","operator":"multiply","operands":[{"kind":"literal","value":0.025},{"kind":"fact","name":"shaft.floor_area","unit":"m2"}]},{"kind":"literal","value":0.10,"unit":"m2"}]},"description":"Freier Querschnitt der Öffnung zur Rauchableitung: mindestens 2,5 v. H. der Fahrschachtgrundfläche, mindestens jedoch 0,10 m²."}],"review":{"status":"draft","machineCheckable":true,"checkMethods":["ids"]}}
,{"schemaVersion":"2.0","id":"mbo-par-39-abs-3-satz-2","source":{"documentId":"mbo","documentTitle":"MUSTERBAUORDNUNG","language":"de","citation":"§ 39 Abs. 3 Satz 2","elements":[{"elementId":"doc/teil-3/abschnitt-6/par-39/abs-3","sentenceId":"doc/teil-3/abschnitt-6/par-39/abs-3/satz-2","role":"primary"}]},"classification":{"type":"permission","normativeCategory":"substantive","summary":"Die Öffnung zur Rauchableitung darf einen Abschluss haben, der im Brandfall selbsttätig öffnet und von mindestens einer geeigneten Stelle aus bedient werden kann."},"applicability":{"targets":[{"entity":"Öffnung zur Rauchableitung","entityType":"smoke_exhaust_opening","description":"Öffnung zur Rauchableitung im Fahrschacht"}]},"requirements":[{"kind":"boolean","fact":"smoke_exhaust_opening.closure_opens_automatically_in_fire","value":true,"description":"Der Abschluss muss im Brandfall selbsttätig öffnen."},{"kind":"numeric","fact":"smoke_exhaust_opening.closure_operable_from_suitable_locations_count","operator":">=","value":1,"unit":"1","description":"Der Abschluss muss von mindestens einer geeigneten Stelle aus bedient werden können."}],"review":{"status":"draft","machineCheckable":true,"checkMethods":["ids"]}}
,{"schemaVersion":"2.0","id":"mbo-par-39-abs-3-satz-3","source":{"documentId":"mbo","documentTitle":"MUSTERBAUORDNUNG","language":"de","citation":"§ 39 Abs. 3 Satz 3","elements":[{"elementId":"doc/teil-3/abschnitt-6/par-39/abs-3","sentenceId":"doc/teil-3/abschnitt-6/par-39/abs-3/satz-3","role":"primary"}]},"classification":{"type":"obligation","normativeCategory":"substantive","summary":"Die Lage der Rauchaustrittsöffnungen muss so gewählt werden, dass der Rauchaustritt durch Windeinfluss nicht beeinträchtigt wird."},"applicability":{"targets":[{"entity":"Rauchaustrittsöffnung","entityType":"smoke_exhaust_outlet","description":"Rauchaustrittsöffnungen im Fahrschacht"}]},"requirements":[{"kind":"boolean","fact":"smoke_exhaust_outlet.position_not_impaired_by_wind","value":true,"description":"Die Lage der Rauchaustrittsöffnungen muss so gewählt werden, dass der Rauchaustritt durch Windeinfluss nicht beeinträchtigt wird."}],"review":{"status":"draft","machineCheckable":false,"checkMethods":["llm_comparison"],"ambiguities":["Die Anforderung ist funktional formuliert; eine maschinelle Prüfung erfordert Lagebeurteilung."]}}
,{"schemaVersion":"2.0","id":"mbo-par-39-abs-4-satz-1","source":{"documentId":"mbo","documentTitle":"MUSTERBAUORDNUNG","language":"de","citation":"§ 39 Abs. 4 Satz 1","elements":[{"elementId":"doc/teil-3/abschnitt-6/par-39/abs-4","sentenceId":"doc/teil-3/abschnitt-6/par-39/abs-4/satz-1","role":"primary"}]},"classification":{"type":"obligation","normativeCategory":"substantive","summary":"Gebäude mit einer Höhe nach § 2 Abs. 3 Satz 2 von mehr als 13 m müssen Aufzüge in ausreichender Zahl haben; dies gilt nicht beim nachträglichen Ausbau und der Nutzungsänderung des obersten Geschosses oder bei der Aufstockung um bis zu zwei Geschosse."},"applicability":{"targets":[{"entity":"Gebäude","entityType":"building","description":"Gebäude mit einer Höhe nach § 2 Abs. 3 Satz 2 von mehr als 13 m"}],"conditions":{"kind":"comparison","fact":"building.height","operator":">","value":13,"valueType":"number","unit":"m"}},"requirements":[{"kind":"boolean","fact":"building.has_sufficient_number_of_elevators","value":true,"description":"Das Gebäude muss Aufzüge in ausreichender Zahl haben."}],"exceptions":[{"kind":"exception","effect":"disapplies_rule","description":"Die Pflicht gilt nicht beim nachträglichen Ausbau und der Nutzungsänderung des obersten Geschosses oder bei der Aufstockung um bis zu zwei Geschosse.","condition":{"kind":"any","conditions":[{"kind":"comparison","fact":"building.modification_type","operator":"in","value":["nachtraeglicher_ausbau_oberstes_geschoss","nutzungsaenderung_oberstes_geschoss"],"valueType":"string_array"},{"kind":"all","conditions":[{"kind":"comparison","fact":"building.modification_type","operator":"==","value":"aufstockung","valueType":"string"},{"kind":"comparison","fact":"building.additional_storeys_count","operator":"<=","value":2,"valueType":"integer"}]}]}}],"references":[{"citation":"§ 2 Abs. 3 Satz 2","elementId":"doc/teil-1/par-2/abs-3","resolution":"resolved","relationship":"defined_by"}],"review":{"status":"draft","machineCheckable":false,"checkMethods":["ids","llm_comparison"],"ambiguities":["'Ausreichende Zahl' ist unbestimmt und bedarf der Interpretation im Einzelfall."]}}
,{"schemaVersion":"2.0","id":"mbo-par-39-abs-4-satz-2","source":{"documentId":"mbo","documentTitle":"MUSTERBAUORDNUNG","language":"de","citation":"§ 39 Abs. 4 Satz 2","elements":[{"elementId":"doc/teil-3/abschnitt-6/par-39/abs-4","sentenceId":"doc/teil-3/abschnitt-6/par-39/abs-4/satz-2","role":"primary"}]},"classification":{"type":"obligation","normativeCategory":"substantive","summary":"Von den Aufzügen muss mindestens einer Kinderwagen, Rollstühle, Krankentragen und Lasten aufnehmen können und Haltestellen in allen Geschossen haben."},"applicability":{"targets":[{"entity":"Aufzug","entityType":"elevator","description":"Aufzüge in Gebäuden mit einer Höhe von mehr als 13 m"}],"conditions":{"kind":"comparison","fact":"building.height","operator":">","value":13,"valueType":"number","unit":"m"}},"requirements":[{"kind":"boolean","fact":"elevator.can_accommodate_prams_wheelchairs_stretchers_loads","value":true,"description":"Mindestens ein Aufzug muss Kinderwagen, Rollstühle, Krankentragen und Lasten aufnehmen können."},{"kind":"boolean","fact":"elevator.has_stops_on_all_storeys","value":true,"description":"Mindestens ein Aufzug muss Haltestellen in allen Geschossen haben."}],"review":{"status":"draft","machineCheckable":true,"checkMethods":["ids"],"ambiguities":["Die Anforderungen beziehen sich auf mindestens einen Aufzug; es ist unklar, ob beide Anforderungen denselben Aufzug betreffen müssen (was der Text nahelegt)."]}}
,{"schemaVersion":"2.0","id":"mbo-par-39-abs-4-satz-3","source":{"documentId":"mbo","documentTitle":"MUSTERBAUORDNUNG","language":"de","citation":"§ 39 Abs. 4 Satz 3","elements":[{"elementId":"doc/teil-3/abschnitt-6/par-39/abs-4","sentenceId":"doc/teil-3/abschnitt-6/par-39/abs-4/satz-3","role":"primary"}]},"classification":{"type":"obligation","normativeCategory":"substantive","summary":"Der Aufzug nach Satz 2 muss von der öffentlichen Verkehrsfläche und von allen Nutzungseinheiten im Gebäude aus stufenlos erreichbar sein."},"applicability":{"targets":[{"entity":"Aufzug","entityType":"elevator","description":"Der Aufzug nach § 39 Abs. 4 Satz 2 (für Kinderwagen, Rollstühle, Krankentragen und Lasten)"}]},"requirements":[{"kind":"boolean","fact":"elevator.step_free_accessible_from_public_traffic_area","value":true,"description":"Der Aufzug muss von der öffentlichen Verkehrsfläche aus stufenlos erreichbar sein."},{"kind":"boolean","fact":"elevator.step_free_accessible_from_all_usage_units","value":true,"description":"Der Aufzug muss von allen Nutzungseinheiten im Gebäude aus stufenlos erreichbar sein."}],"review":{"status":"draft","machineCheckable":true,"checkMethods":["ids"]}}
,{"schemaVersion":"2.0","id":"mbo-par-39-abs-4-satz-4","source":{"documentId":"mbo","documentTitle":"MUSTERBAUORDNUNG","language":"de","citation":"§ 39 Abs. 4 Satz 4","elements":[{"elementId":"doc/teil-3/abschnitt-6/par-39/abs-4","sentenceId":"doc/teil-3/abschnitt-6/par-39/abs-4/satz-4","role":"primary"}]},"classification":{"type":"conditional_requirement","normativeCategory":"substantive","summary":"Haltestellen im obersten Geschoss, im Erdgeschoss und in den Kellergeschossen sind nicht erforderlich, wenn sie nur unter besonderen Schwierigkeiten hergestellt werden können."},"applicability":{"targets":[{"entity":"Aufzug-Haltestelle","entityType":"elevator_stop","description":"Haltestellen im obersten Geschoss, im Erdgeschoss und in den Kellergeschossen"}],"conditions":{"kind":"comparison","fact":"elevator_stop.can_only_be_installed_with_special_difficulty","operator":"==","value":true,"valueType":"boolean"}},"requirements":[{"kind":"boolean","fact":"elevator_stop.is_required","value":false,"description":"Haltestellen im obersten Geschoss, im Erdgeschoss und in den Kellergeschossen sind nicht erforderlich, wenn sie nur unter besonderen Schwierigkeiten hergestellt werden können."}],"review":{"status":"draft","machineCheckable":false,"checkMethods":["llm_comparison"],"ambiguities":["'Besondere Schwierigkeiten' ist ein unbestimmter Rechtsbegriff und bedarf der Einzelfallbeurteilung."]}}
